H,W=len(g),len(g[0]); seen=set(); comps=[]
for r in range(H):
 for c in range(W):
  if g[r][c] and (r,c) not in seen:
   col=g[r][c]; stack=[(r,c)]; seen.add((r,c)); cells=[]
   while stack:
    x,y=stack.pop(); cells.append((x,y))
    for p in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
     a,b=p
     if 0<=a<H and 0<=b<W and g[a][b]==col and p not in seen: seen.add(p); stack.append(p)
   comps.append((col,cells))
# rightmost-first settle each rigid component against existing other cells
out=[[0]*W for _ in range(H)]
for col,cells in sorted(comps,key=lambda x:max(c for r,c in x[1]), reverse=True):
 shift=0
 while True:
  nxt=[(r,c+shift+1) for r,c in cells]
  if any(c>=W or out[r][c] for r,c in nxt): break
  shift+=1
 for r,c in cells: out[r][c+shift]=col
 print(col, sorted(cells), 'shift',shift)
print('\n'.join(' '.join(map(str,row)) for row in out))

